fn is_palindrome(text: Vec<char>) -> bool {
    let n = text.len();
    let mut i = 0;
    let mut j = n.wrapping_sub(1); // handles empty case when n=0
    
    while i < j {
        let left_char = text[i];
        let right_char = text[j];
        
        // Convert to lowercase if ASCII uppercase
        let left_lower = if left_char.is_ascii_uppercase() {
            left_char.to_ascii_lowercase()
        } else {
            left_char
        };
        
        let right_lower = if right_char.is_ascii_uppercase() {
            right_char.to_ascii_lowercase()
        } else {
            right_char
        };
        
        if left_lower != right_lower {
            return false;
        }
        
        i += 1;
        j = j.wrapping_sub(1);
    }
    
    true
}